mapper.select:
SELECT mc.id AS memberCouponId, mc.coupon_id AS couponId, mc.member_id AS memberId, c.name AS couponName, mc.issued_at AS issuedAt, c.starts_at AS startsAt, c.expires_at AS expiresAt FROM member_coupons mc INNER JOIN coupons c ON c.id = mc.coupon_id WHERE mc.status = 'AVAILABLE' AND c.status = 'ACTIVE' AND c.starts_at <= NOW(6) AND c.expires_at > NOW(6) AND c.expires_at <= DATE_ADD(NOW(6), INTERVAL #{days} DAY)
AND ( c.expires_at > #{lastExpiresAt} OR (c.expires_at = #{lastExpiresAt} AND mc.id > #{lastMemberCouponId}) )
ORDER BY c.expires_at ASC, mc.id ASC LIMIT #{limit}
